154     else if (ArrayType *ATy = dyn_cast<ArrayType>(EltTy)) {
155       if (IdxVal >= ATy->getNumElements())
156         return nullptr;
157       EltTy = ATy->getElementType();
158     } else {
159       return nullptr; // Unknown type.
160     }
161 
162     LaterIndices.push_back(IdxVal);
163   }
