8155   // fcmp oge X, -inf -> fcmp ord X, 0
8156   // fcmp ult X, -inf -> fcmp uno X, 0
8157   // fcmp ule X, -inf -> fcmp ueq X, -inf
8158   // fcmp ugt X, -inf -> fcmp une X, -inf
