8177     case FCmpInst::FCMP_OGE:
8178       return new FCmpInst(FCmpInst::FCMP_OEQ, Op0, Op1, "", &I);
8179     case FCmpInst::FCMP_ULT:
8180       return new FCmpInst(FCmpInst::FCMP_UNE, Op0, Op1, "", &I);
8181     case FCmpInst::FCMP_UGT:
